import { ValidationError } from './errors.js';

/** The type without the given keys, applied to every member of a union. */
export type FacadeWithout<T, K extends PropertyKey> = T extends unknown ? Omit<T, K> : never;

/** The given keys of T, each required. A key T does not have is ignored. */
export type FacadeRequire<T, K extends PropertyKey> = Required<Pick<T, Extract<K, keyof T>>>;

/**
 * The arguments from the body on: the body may be left out when `{}` satisfies it, that is when the
 * method's own pins took every required key. `Tail` is what follows it, all optional.
 */
export type FacadeBodyArgs<B, Tail extends unknown[]> = {} extends B ? [data?: B, ...Tail] : [data: B, ...Tail];

/**
 * The JSON answer of an operation that also answers bytes under the same status: the promise
 * without its byte members (`data` an ArrayBuffer or a Blob). A promise with none is unchanged.
 */
export type FacadeJson<P> = P extends Promise<infer R> ? Promise<Exclude<R, { data: ArrayBuffer | Blob }>> : P;

/** Refuse a caller-supplied value for a key the method fixes or does not take. */
export function facadeRefuse(label: string, given: Record<string, unknown>, keys: readonly string[]): void {
  for (const key of keys) {
    if (given[key] !== undefined) {
      throw new ValidationError(label + ' does not take ' + JSON.stringify(key) + ': the method sets it', key);
    }
  }
}

/** Refuse a body that lacks a field the method needs. */
export function facadeRequire(label: string, body: Record<string, unknown> | undefined, key: string): void {
  if (body === undefined || body === null || body[key] === undefined) {
    throw new ValidationError(label + ' requires ' + JSON.stringify(key), key);
  }
}

/** Refuse a body field whose value is not one the method allows. */
export function facadeRestrict(label: string, body: Record<string, unknown> | undefined, key: string, allowed: readonly unknown[]): void {
  const value = body?.[key];
  if (value !== undefined && !allowed.includes(value)) {
    throw new ValidationError(label + ' takes ' + JSON.stringify(key) + ' as one of ' + allowed.map((v) => JSON.stringify(v)).join(', '), key);
  }
}

/** Is the value a byte body: a Blob, ArrayBuffer, typed array or stream? */
export function facadeIsBytes(value: unknown): boolean {
  return value instanceof ArrayBuffer
    || ArrayBuffer.isView(value)
    || (typeof Blob !== 'undefined' && value instanceof Blob)
    || (typeof ReadableStream !== 'undefined' && value instanceof ReadableStream);
}
